function heapPush(heap, value) {
  const h = heap.slice();
  h.push(value);
  let i = h.length - 1;
  while (i > 0) {
    const p = Math.floor((i - 1) / 2);
    if (h[p] <= h[i]) break;
    const t = h[p]; h[p] = h[i]; h[i] = t;
    i = p;
  }
  return h;
}

