function topK(items, k) {
  const heap = [];                       // min-heap of the k largest so far
  for (const x of items) {
    heapPush(heap, x);
    if (heap.length > k) heapPop(heap);  // drop the smallest of the k+1
  }
  return heap.slice().sort((a, b) => a - b);
}

// The root is the WEAKEST member of the current answer, so one
// comparison against it rejects most candidates immediately.
console.log(topK([5, 1, 9, 3, 7], 3));  // [5, 7, 9]

//     y            rotate right at y           x
//    / \          ------------------->        / \
//   x   C                                    A   y
//  / \                                          / \
// A   B          in-order: A x B y C           B   C

function rotateRight(y) {
  const x = y.left;
  y.left = x.right;   // B changes sides: it is > x and < y
  x.right = y;
  return x;           // x is the new root of this subtree
}

