function isBalanced(root) {
  const height = (n) => {
    if (n === null) return 0;
    return 1 + Math.max(height(n.left), height(n.right));
  };
  const check = (n) => {
    if (n === null) return true;
    if (Math.abs(height(n.left) - height(n.right)) > 1) return false;
    return check(n.left) && check(n.right);
  };
  return check(root);
}

