function heapPop(heap) {
  if (heap.length === 0) return [null, []];
  const h = heap.slice();
  const min = h[0];
  const last = h.pop();
  if (h.length > 0) {
    h[0] = last;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1, r = 2 * i + 2;
      let smallest = i;
      if (l < h.length && h[l] < h[smallest]) smallest = l;
      if (r < h.length && h[r] < h[smallest]) smallest = r;
      if (smallest === i) break;
      const t = h[i]; h[i] = h[smallest]; h[smallest] = t;
      i = smallest;
    }
  }
  return [min, h];
}

