function topK(items, k) {
  if (k <= 0) return [];
  const h = [];
  const push = (v) => {
    h.push(v);
    let i = h.length - 1;
    while (i > 0) {
      const p = Math.floor((i - 1) / 2);
      if (h[p] <= h[i]) break;
      const t = h[p]; h[p] = h[i]; h[i] = t;
      i = p;
    }
  };
  const pop = () => {
    const last = h.pop();
    if (h.length > 0) {
      h[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = 2 * i + 2;
        let smallest = i;
        if (l < h.length && h[l] < h[smallest]) smallest = l;
        if (r < h.length && h[r] < h[smallest]) smallest = r;
        if (smallest === i) break;
        const t = h[i]; h[i] = h[smallest]; h[smallest] = t;
        i = smallest;
      }
    }
  };
  for (const x of items) {
    push(x);
    if (h.length > k) pop();
  }
  const out = [];
  while (h.length > 0) { out.push(h[0]); pop(); }
  return out;
}

