exam.solution:
function mergeSortedLists(lists) {
  const h = [];
  const less = (a, b) => a[0] < b[0];
  const push = (e) => {
    h.push(e);
    let i = h.length - 1;
    while (i > 0) {
      const p = Math.floor((i - 1) / 2);
      if (!less(h[i], h[p])) break;
      const t = h[p]; h[p] = h[i]; h[i] = t;
      i = p;
    }
  };
  const pop = () => {
    const top = h[0];
    const last = h.pop();
    if (h.length > 0) {
      h[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = 2 * i + 2;
        let smallest = i;
        if (l < h.length && less(h[l], h[smallest])) smallest = l;
        if (r < h.length && less(h[r], h[smallest])) smallest = r;
        if (smallest === i) break;
        const t = h[i]; h[i] = h[smallest]; h[smallest] = t;
        i = smallest;
      }
    }
    return top;
  };
  for (let j = 0; j < lists.length; j++) {
    if (lists[j].length > 0) push([lists[j][0], j, 0]);
  }
  const out = [];
  while (h.length > 0) {
    const [value, j, idx] = pop();
    out.push(value);
    if (idx + 1 < lists[j].length) push([lists[j][idx + 1], j, idx + 1]);
  }
  return out;
}
